import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"系统设置","description":"","frontmatter":{},"headers":[],"relativePath":"backend/settings.md","filePath":"backend/settings.md","lastUpdated":1794049926000}`),a={name:`backend/settings.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to “系统设置”">​</a></h1><p>本页说明参数配置、字典与业务编号，适用于后端开发者与运营配置人员。</p><p>Settings 包（Tier 2）提供参数配置、字典与业务编号三类「运行时可调」的数据，并通过 <code>Contracts</code> 的 <code>IConfigValueReader</code> 与 <code>INumberGenerator</code> 供其他包使用。三类都是平台库实体、实现 <code>IOwnedByTenant</code>：平台一份，租户可以有自己的；读共享，写只在本侧。</p><div class="tip custom-block"><p class="custom-block-title">和 appsettings 的区别</p><p><code>appsettings.json</code> 的 <code>BasicApp:*</code> 是部署配置（改了要重启，见<a href="./../configuration">配置参考</a>）；本页的参数是运营配置，存在库里、后台改了即生效，租户可以覆盖。</p></div><h2 id="参数配置" tabindex="-1">参数配置 <a class="header-anchor" href="#参数配置" aria-label="Permalink to “参数配置”">​</a></h2><p><code>SysConfig</code>：键、名称、分组、值、缺省值、数据类型、是否加密、是否内置、是否允许租户覆盖、状态、排序、说明。</p><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>键</td><td>3–128 位，创建后不可改；本侧唯一</td></tr><tr><td>数据类型</td><td><code>Text</code>、<code>Number</code>、<code>Boolean</code>、<code>Json</code>、<code>Array</code>，按类型校验值与缺省值</td></tr><tr><td>加密</td><td>值经 <code>ISecretProtector</code> 加密存放，不回显（<code>value</code> 为空、<code>hasValue</code> 标出）；更新时留空即保留原值；开关加密会就地加密或解密现值</td></tr><tr><td>租户覆盖</td><td>租户新建与平台参数同键的参数即覆盖它；平台参数 <code>allowTenantOverride = false</code> 时拒绝</td></tr><tr><td>生效值</td><td><code>IConfigValueReader</code>：只看启用的参数 → 当前租户的同键参数优先、其次平台的 → 值为空回落缺省值 → 加密值解密后返回</td></tr></tbody></table><p>操作 <code>configs.create / get / list / update / delete</code>，权限 <code>settings.configs.*</code>（两侧）；内置参数不可删。</p><h3 id="代码读取的参数" tabindex="-1">代码读取的参数 <a class="header-anchor" href="#代码读取的参数" aria-label="Permalink to “代码读取的参数”">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>谁读</th><th>含义</th></tr></thead><tbody><tr><td><code>identity.login-methods</code></td><td>Identity</td><td>登录页开放的方式（逗号分隔，只认平台的）：<code>password</code>、<code>email</code>、<code>phone</code>；没建即只有密码登录，写错即登录配置报错</td></tr><tr><td><code>identity.password</code></td><td>Identity</td><td>密码设置（JSON，只认平台的）：<code>forceChange</code> 缺省 <code>false</code>，打开后密码由他人设置的账号凭密码登录要先改密，见<a href="./authentication#强制修改由他人设置的密码">统一认证</a></td></tr><tr><td><code>identity.impersonation</code></td><td>Identity</td><td>模仿登录（JSON）：<code>sessionMinutes</code> 缺省 30、<code>notifyTarget</code> 缺省 <code>true</code>；写错即不能发起，见<a href="./authentication#模仿登录">统一认证</a></td></tr><tr><td><code>auditing.retention-days</code></td><td>Auditing</td><td>日志保留天数（1–3650），没建即 180 天</td></tr><tr><td><code>access.security.login-auto-ban</code></td><td>Access</td><td>登录失败自动封禁（JSON，只认平台的，缺省关闭）</td></tr><tr><td><code>notification.telegram</code>、<code>notification.telegram.webhook-secret-token</code></td><td>Notification</td><td>Telegram 的总开关、Webhook 根地址与网络设置（JSON，只认平台的，缺省关）与 Webhook 密钥（加密参数）</td></tr><tr><td><code>chat.policy</code></td><td>Chat</td><td>聊天策略（JSON）：<code>retentionDays</code>（1–3650，缺省 365）与 <code>sensitiveWords</code>；写错即失败，不按错误的值删数据或放过敏感词</td></tr></tbody></table><h2 id="字典" tabindex="-1">字典 <a class="header-anchor" href="#字典" aria-label="Permalink to “字典”">​</a></h2><p><code>SysDict</code> + <code>SysDictItem</code>：字典码、名称、状态；字典项是同一字典内无环的树，带值、标签、排序、缺省项（字典内唯一，设新的即清掉旧的）与 JSON 元数据。</p><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>字典码</td><td>创建后不可改；平台新建要求全库无同码，租户新建要求平台与本租户都无同码（字典不覆盖）</td></tr><tr><td>可见性</td><td>读共享：平台字典 + 本租户字典；租户改不了平台字典</td></tr><tr><td>停用</td><td>停用的字典不再出现在下拉选项里</td></tr></tbody></table><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>dicts.create / get / list / update / delete</code></td><td><code>settings.dicts.*</code></td><td>管理字典</td></tr><tr><td><code>dict-items.create / get / list / tree / update / delete</code></td><td><code>settings.dict-items.*</code></td><td>管理字典项</td></tr><tr><td><code>dicts.options</code></td><td>登录即可</td><td>业务表单的下拉（<code>GET /api/dicts:options?code=</code>）</td></tr></tbody></table><p><code>dict-items.list</code> 分页检索字典项（按 <code>dictId</code> 筛选某本字典，关键字匹配编码、名称与附加值），<code>dict-items.tree</code> 一次取整本字典的项（深度优先、带层级，同级按排序号再按编码，给上级选择与级联取值用）。<code>dicts.list / get / options</code> 与 <code>dict-items.list / tree</code> 也是 MCP / AI 工具。前端 SchemaPage 的字典列与壳层的 <code>dictApi.options</code> 都接在 <code>dicts.options</code> 上。</p><p>系统不依赖任何内置字典；演示字典由种子 <code>settings.demo</code> 在演示开关打开时写入。</p><h2 id="业务编号" tabindex="-1">业务编号 <a class="header-anchor" href="#业务编号" aria-label="Permalink to “业务编号”">​</a></h2><p><code>SysNumberingRule</code> + <code>SysNumberingAllocation</code>：编码、前缀、分隔符、日期格式（<code>None</code>、<code>Yyyy</code>、<code>YyyyMM</code>、<code>YyyyMMdd</code>、<code>YyMM</code>、<code>YyMMdd</code>、<code>MMdd</code>）、流水长度、重置周期（<code>Never</code>、<code>Daily</code>、<code>Monthly</code>、<code>Yearly</code>）、时区（缺省 <code>UTC</code>）。</p><ul><li>发号在独立的作用域与事务里完成（<code>StoreScope</code>），号一经发出永久消耗、外层调用失败也不回收、允许空洞；先对规则行加锁更新，同一规则的发号由此串行，并发发号不重复。</li><li>幂等键：同一幂等键参数相同即重放（<code>isReplay</code>），不同即 <code>SETTINGS_CONFLICT_013</code>。</li><li>日期格式要能区分重置周期，时区要能解析，流水位数要装得下已发出的流水值。</li><li>租户看得见自己的规则与平台标为「供租户使用」的规则，只能改自己的；编码在所属一侧内唯一。</li></ul><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>numbering-rules.create / get / list / update / delete</code></td><td><code>settings.numbering-rules.*</code></td><td></td></tr><tr><td><code>numbering-rules.preview</code></td><td><code>settings.numbering-rules.read</code></td><td>按格式在当前时刻拼出号码，不读库、不发号</td></tr><tr><td><code>numbering-rules.generate</code></td><td><code>settings.numbering-rules.generate</code></td><td>发号（也可由其他包经 <code>INumberGenerator</code> 调用）</td></tr><tr><td><code>numbering-rules.allocations</code></td><td><code>settings.numbering-rules.read</code></td><td>发号记录</td></tr><tr><td><code>numbering-rules.reset</code></td><td><code>settings.numbering-rules.reset</code></td><td>重置流水，理由必填（进操作审计）</td></tr></tbody></table><h2 id="用户设置" tabindex="-1">用户设置 <a class="header-anchor" href="#用户设置" aria-label="Permalink to “用户设置”">​</a></h2><p>个人偏好不在 Settings，而在 Identity 的 <code>SysUserSetting</code>（用户 × 场景 <code>Preference</code> / <code>Page</code> × 键，值是 JSON）：<code>user-settings.get</code> / <code>update</code>（只要求登录）。壳层的偏好、收藏、列表的个人视图与列设置、工作台看板布局都存在这里，改了经 <code>UserSettingChanged</code> 推到同一用户的其他设备。</p><h2 id="页面" tabindex="-1">页面 <a class="header-anchor" href="#页面" aria-label="Permalink to “页面”">​</a></h2><p><code>src/modules/settings</code>：参数配置（租户行可「覆盖此参数」）、字典（主从两栏）、业务编号（预览与发号记录）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./../configuration">配置参考</a> · <a href="./messaging">消息通知</a> · <a href="./access-policy">访问策略与权限条件</a></li></ul>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};